CATEGORIES=[]
def category(id, name, subtitle, era, question, intro, insight, sources):
    item=dict(id=id,name=name,subtitle=subtitle,era=era,question=question,intro=intro,insight=insight,sources=sources,methods=[])
    CATEGORIES.append(item)
    return item
def method(c,title,tag,idea,formula,example,use,limit,refs):
    c['methods'].append(dict(title=title,tag=tag,idea=idea,formula=formula,example=example,use=use,limit=limit,refs=refs))

c=category('boolean','Boolean & exact','Sets, phrases and constraints','1950s → today','Does this document satisfy the rule?',
 'Start with a library: each index term points to a set of documents. AND intersects sets, OR unites them, and NOT removes documents relative to the collection. The answer is membership; pure Boolean retrieval does not order the matches by relevance.',
 'Exact conditions still matter inside modern systems: an identifier, a quoted phrase, a date range or a permission filter can be more important than a high similarity score.',['boolean','booldocs'])
method(c,'Boolean set retrieval','FOUNDATION','Evaluate a query as a set expression over postings lists. Parentheses and operator precedence determine its meaning.','(A AND B) OR C = (A ∩ B) ∪ C','“battery AND storage” returns only documents with both tokens. “battery OR storage” also finds documents with just one.','Auditable expert search and hard inclusion/exclusion rules.','Vocabulary mismatch and an all-or-nothing answer; an OR query can return many unordered results.',['boolean'])
method(c,'Phrase & proximity retrieval','POSITIONAL','Store token positions, then require adjacency or a bounded separation. This adds word order to ordinary term membership.','phrase("energy storage") ⇒ position(storage) = position(energy) + 1','“energy storage policy” matches the phrase; “storage for renewable energy” does not. A proximity query could admit both.','Names, legal language, exact quotations and technical phrases.','Tokenizer choices, punctuation and phrase slop change what “exact” means.',['boolean'])
method(c,'Fielded & filtered retrieval','CONSTRAINT','Apply rules to structured metadata and fields, then rank only eligible documents or intersect eligible sets during search.','eligible(d) = type(d)=report AND year(d)≥2020','Search “battery”, restricting results to reports published since 2020. The best-scoring ineligible article is still excluded.','Catalog search, tenant restrictions, product facets and precise identifiers.','Filtering after shallow ANN retrieval can leave too few candidates; filter semantics must be consistent across branches.',['booldocs'])
method(c,'Fuzzy & character-level matching','ROBUSTNESS','Match spelling variants using edit distance, character n-grams or prefix dictionaries before, or alongside, lexical ranking.','edit_distance("batery", "battery") = 1','A fuzzy dictionary lookup repairs “batery”; it does not infer that “accumulator” is a synonym.','Typos, autocomplete, OCR noise and inconsistent naming.','Short tokens and identifiers can produce costly or incorrect expansions; fuzziness is not semantic understanding.',['boolean'])

c=category('lexical','Lexical & vector space','From yes/no to an ordered list','1960s–1970s → today','Which matching words carry the most evidence?',
 'Rank partial matches using term importance. Frequent terms within a document can help, but words found everywhere should count less. A term vector makes each vocabulary item a dimension; cosine compares direction rather than raw magnitude.',
 'Lexical vectors are sparse, interpretable and particularly useful for rare names, codes and exact terminology. A vector does not have to be a neural embedding.',['vsm','neural'])
method(c,'TF–IDF weighting','TERM WEIGHTS','Combine within-document frequency with inverse collection frequency. Many variants exist; the lab states its exact convention.','w(t,d) = tf(t,d) × [ln((N+1)/(df(t)+1)) + 1]','If “lithium” appears in 2 of 8 documents, its smoothed IDF is ln(9/3)+1 = 2.099. A token in all 8 has IDF 1.','A transparent baseline, document similarity and sparse feature construction.','Linear term counts can overreward repetition; tokenization and weighting variants matter.',['vsm'])
method(c,'Cosine vector-space retrieval','GEOMETRY','Weight queries and documents in the same term space and normalize their dot product. Partial lexical overlap receives a graded score.','cos(q,d) = (q · d) / (||q||₂ ||d||₂)','[1,1] and [2,2] have cosine 1. A longer document with exactly proportional weights has the same direction.','Fast sparse ranking and interpretable feature-based similarity.','Unrelated meanings of the same word still match; synonyms in different dimensions do not overlap automatically.',['vsm'])
method(c,'Field boosts & structured term weighting','FEATURES','Give title, body and other fields different influence. A simple boost is a heuristic; BM25F additionally models field-specific normalization.','score = 2 × title_score + body_score','“battery storage” in a title may carry more weight than one occurrence in a long footnote.','Products, scientific papers, documentation and metadata-rich search.','Untuned boosts can encode bad assumptions. Do not confuse arbitrary score addition with a calibrated probability.',['bm25'])

c=category('probabilistic','Probabilistic & language models','Uncertainty becomes a scoring rule','1970s–1990s → today','How much evidence supports relevance?',
 'Probabilistic models formalize uncertainty about relevance. BM25 adds diminishing returns for repeated terms and a document-length adjustment. Query-likelihood models instead ask how likely the query is under a smoothed document language model.',
 'BM25 is a lexical scoring function with probabilistic roots. The BM25 score shown here is not a probability that the document is relevant.',['prob','bm25','lm'])
method(c,'Probability Ranking Principle & BIM','PROBABILITY','Under a binary relevance objective and the model assumptions, rank by estimated relevance probability. The Binary Independence Model derives weights using term-presence evidence.','rank by P(R=1 | q,d); BIM uses term-presence log odds','A rare query term may be more likely in relevant than irrelevant documents and therefore contribute positive evidence.','Understanding why relevance evidence can be added in log space.','Independence and binary-relevance assumptions simplify language and user utility. The principle does not specify a perfect estimator.',['prob'])
method(c,'Okapi BM25','STRONG BASELINE','Saturate term frequency and normalize for length. The lab uses a positive log1p IDF variant and counts each unique query term once.','Σ IDF(t) × tf(t,d)(k₁+1) / [tf(t,d)+k₁(1−b+b|d|/avgdl)]','With k₁=1.2, b=.75 and |d|=avgdl, the TF multiplier rises from 1.000 at tf=1 to 1.375 at tf=2, then approaches 2.2.','General text retrieval, hybrid search and rare exact terminology.','No semantic matching by itself. Length, language and tokenization settings require validation.',['bm25','bm25teach'])
method(c,'BM25F & probabilistic extensions','FIELDS','Model multiple document fields with distinct weights and length normalization before applying saturation.','weighted_tf = Σfield boost(field) × normalized_tf(field)','A short title and a long body should not necessarily receive the same length correction.','Documents with titles, abstracts, tags and anchor text.','A field-weighted score is not necessarily BM25F; implementation details affect comparability.',['bm25'])
method(c,'Query likelihood & smoothing','LANGUAGE MODEL','Estimate the probability of query tokens from a document model. Smoothing shares probability with a collection model to handle absent words.','log P(q|d) = Σt count(t,q) × log[(tf(t,d)+μP(t|C))/(|d|+μ)]','For tf=2, |d|=10, P(t|C)=.01 and μ=100, the smoothed probability is 3/110 = .0273.','An alternative lexical baseline and foundation for relevance language models.','The lab demonstrates later Dirichlet smoothing, not an exact reimplementation of Ponte–Croft’s original estimator.',['lm','prob'])
method(c,'Divergence from randomness & relevance models','RELATED BRANCHES','Other statistical families score departures from a background distribution or estimate a relevance-language model from feedback.','more surprising term evidence → potentially larger relevance weight','A term unusually frequent in a small set of relevant documents can receive more weight than a background-common term.','Alternative term-weighting designs and pseudo-feedback systems.','These are distinct modeling families; this conceptual summary is not one shared scoring equation.',['bm25'])

c=category('expansion','Query & document expansion','Bridge the vocabulary gap','1971 → today','Can we express the information need better?',
 'The first query is often incomplete. Expand it with synonyms, feedback or generated alternatives; alternatively, expand documents offline with questions they could answer. Query reformulation changes the request, while document expansion changes what is indexed.',
 'Expansion trades coverage against drift. A fluent generated query or hypothetical answer is a search aid; it is not evidence for the final answer.',['feedback','rocchio','doc2query','hyde'])
method(c,'Thesaurus, normalization & synonym expansion','LEXICAL','Map alternate forms to a common representation or add related terms. Keep exact identifiers intact when normalization would change meaning.','battery → battery OR accumulator','“car” and “automobile” may be linked in a controlled vocabulary. “Java” requires context before expanding.','Domain abbreviations, multilingual aliases and predictable terminology.','Polysemy can add the wrong sense. Stemming can merge distinct words and does not solve every synonym.',['feedback'])
method(c,'Rocchio relevance feedback','JUDGED FEEDBACK','Move the query vector toward the centroid of judged relevant documents and away from judged irrelevant documents.','q′ = αq + β mean(relevant) − γ mean(nonrelevant)','q=[1,0], relevant=[0,1], α=1, β=.5, γ=0 gives q′=[1,.5]. The direction moves toward the second dimension.','Interactive search where users can label a few useful results.','Incorrect judgments and multiple relevant clusters can pull the query in an unhelpful direction.',['rocchio'])
method(c,'Pseudo-relevance feedback · RM3 family','ASSUMED FEEDBACK','Treat the top results as useful, estimate expansion terms from them and mix those terms with the original query.','q′ = (1−λ) q + λ feedback_model(top-k)','For “jaguar speed”, top car reviews may inject “engine” even when the user meant the animal.','Improving underspecified queries when initial retrieval is reasonably accurate.','Top-ranked does not imply relevant. Wrong initial evidence causes query drift.',['feedback','bm25'])
method(c,'doc2query / document expansion','OFFLINE GENERATION','Predict questions a document could answer, append them to its searchable representation, then use an ordinary lexical index.','document → generated queries → expanded index','A passage about grid stabilization is indexed with the predicted query “why do batteries help renewable power?”','Moving generation cost to indexing time and improving lexical recall.','Index growth, generated mistakes and refresh cost. Generated text must retain its distinction from original evidence.',['doc2query'])
method(c,'LLM rewrite, multi-query & HyDE','ONLINE GENERATION','Rewrite or decompose the query; retrieve several alternatives and merge them. HyDE embeds a hypothetical document to locate actual documents.','q → hypothetical document → encoder → nearest real documents','“power after sunset” can become “solar battery storage at night”. A hypothesis about storage points search toward real passages.','Vocabulary mismatch, conversational context and complex requests.','Generated details can bias the search. More queries mean more cost, duplicates and fusion decisions.',['hyde','diver'])

c=category('dense','Dense semantic retrieval','Learn where meaning lives','1990s → today','Can two different phrasings be neighbors?',
 'Dense retrieval maps a query and each item to compact vectors. Search uses dot product, cosine or a distance suited to the trained model. Unlike a cross-encoder, a bi-encoder represents the document independently of the current query.',
 'The lab uses hand-authored two-dimensional vectors to make geometry visible. Real embedding coordinates are distributed and usually do not have named human concepts.',['lsi','sbert','dpr','qwen'])
method(c,'LSI / latent semantic indexing','BEFORE NEURAL RETRIEVAL','Factorize a term-document matrix with truncated SVD. Shared latent factors can connect documents that use different words.','X ≈ Uₖ Σₖ Vₖᵀ','Documents about “cars” and “automobiles” can share a factor when their surrounding word patterns overlap.','Understanding early latent semantics and low-rank compression.','Linear factors, corpus dependence and expensive updates; dimensionality affects which distinctions survive.',['lsi'])
method(c,'Bi-encoders · SBERT & DPR','INDEPENDENT ENCODING','Encode a query and document separately. Precompute document embeddings, then score incoming queries against them.','score(q,d) = Equery(q) · Edoc(d)','“store solar power overnight” can match “batteries shift daytime generation to evening” despite limited word overlap.','Semantic first-stage retrieval and reusable vector indexes.','A single vector can blur negation, exact identifiers and multiple topics; training distribution matters.',['sbert','dpr'])
method(c,'Contrastive learning & hard negatives','TRAINING','Train relevant pairs to score above irrelevant pairs. Hard negatives look plausible but fail the intended relevance criterion.','L = −log exp(s(q,d⁺)/τ) / Σj exp(s(q,dj)/τ)','For a query about battery recycling, battery manufacturing is a harder negative than a recipe.','Teaching embeddings task-specific notions of relevance.','False negatives punish useful matches. Training contamination and biased negatives can inflate evaluation.',['dpr','qwen'])
method(c,'Instruction-tuned & multilingual embeddings','TASK CONDITIONING','Condition representations on the retrieval task and train across tasks or languages. The same text may need different representations for different goals.','E(instruction, query) → task-aware vector','“Find papers supporting this claim” differs from “find papers contradicting this claim”.','Cross-language search, code search and specialized retrieval instructions.','Follow the model’s required prefixes and similarity convention; performance is task-dependent, not universally superior.',['qwen'])

c=category('sparse','Learned sparse retrieval','Neural semantics, lexical coordinates','2021 → today','Can a model learn better vocabulary weights?',
 'A learned sparse representation retains vocabulary-sized dimensions but activates only a small subset. Neural models learn weights and sometimes add terms absent from the original text. Query and document vectors can still be matched through an inverted index.',
 'Sparse versus dense describes representation; learned versus hand-designed describes how weights are obtained. BM25 and SPLADE are both sparse but learn very different things.',['splade','impact'])
method(c,'Learned term impacts','TERM REWEIGHTING','Predict which indexed terms matter most instead of relying entirely on a fixed TF/IDF formula. Some systems pair this with generated document expansion.','score(q,d) = Σt wquery(t) × wdoc(t)','A model can give “storage” more impact than a generic “system” in a battery article.','Efficient inverted-index retrieval with learned term salience.','Learned weights require training and specialized indexing choices; expansion and impact prediction are separate design decisions.',['impact'])
method(c,'SPLADE sparse expansion','VOCABULARY PROJECTION','Produce nonnegative vocabulary weights using a language model, aggregation and sparsity regularization. Expanded terms allow lexical-space semantic matching.','s(q,d) = Σvocabulary wq(t) wd(t)','“renewable storage” may activate “battery”, allowing a nonzero dot product with a document containing that term.','Semantic coverage with inspectable vocabulary coordinates.','More active terms improve some matches but increase index size and postings work. Weights are not explanations of model reasoning.',['splade'])
method(c,'Pruning, quantization & sparsity regularization','EFFICIENCY','Control the number or precision of active term weights at training or indexing time, balancing matching quality and retrieval cost.','keep(t) ⇔ w(t) ≥ threshold','At threshold .5, weights battery=.9, grid=.6, car=.2 retain two terms. A useful low-weight expansion may disappear.','Making neural sparse retrieval serve at practical latency and memory budgets.','An aggressive threshold can remove the only bridge to a relevant document; measure retrieval quality after pruning.',['splade','impact'])

c=category('late','Late interaction','Keep the words, defer the matching','2020 → today','Which document token best supports each query token?',
 'Multi-vector models retain token-level representations. Document encoding happens ahead of time; token interactions happen during search. ColBERT uses each query token’s best matching document token, then adds these maxima.',
 'Late interaction sits between one-vector compression and full query-document cross-attention. It can retrieve directly using a specialized index or rerank an existing candidate set.',['colbert','colbert2'])
method(c,'ColBERT & MaxSim','MULTI-VECTOR','For each query token, select the largest similarity with any document token, then sum the selected values.','score = Σi maxj (qi · dj)','For query tokens “solar” and “storage”, row maxima .9 and .8 produce score 1.7. A document good at only “solar” receives less support.','Fine-grained semantic matches without jointly encoding every pair.','Larger vector storage and matching work; a token can support several query tokens, so MaxSim is not one-to-one alignment.',['colbert'])
method(c,'ColBERTv2 & compressed interaction','COMPRESSION','Reduce multi-vector storage with residual compression and improve training through denoised supervision.','document tokens → compressed vectors → approximate interaction','Keep many token-level clues while shrinking their representation, instead of dropping all but one passage vector.','Deploying late interaction at larger corpus scale.','Compression and candidate pruning can alter scores. Quality and memory claims depend on the evaluated setup.',['colbert2'])
method(c,'Passage aggregation & multi-vector items','LONG DOCUMENTS','Represent a long item by chunks, token vectors or several learned vectors. Aggregate evidence and deduplicate at the parent-document level.','doc_score = max passage_score  (one possible rule)','A report about batteries and wind may need two chunks to preserve its separate topics.','Long reports, scientific documents and records with several evidence views.','Max, sum and learned aggregation behave differently. Duplicate overlapping chunks can distort fusion and crowd out other sources.',['transformers','colbert'])

c=category('indexes','Indexes & efficient search','How scoring becomes a service','1960s → today','How do we avoid scoring everything?',
 'The retrieval model defines matching; the index and search algorithm decide how to execute it. Inverted indexes support sparse scores. Approximate nearest-neighbor indexes trade search completeness for speed or memory when looking up vectors.',
 'ANN recall measures agreement with exact vector neighbors. Relevance recall measures useful documents recovered. A perfect vector index cannot fix an embedding model that ranks the wrong documents.',['boolean','hnsw','faiss'])
method(c,'Inverted indexes, WAND & block pruning','SPARSE EXECUTION','Use postings lists for terms and safe score upper bounds to skip candidates that cannot enter the current top-k.','skip block if upper_bound(block) < current kth score','If a postings block can score at most .4 and the current kth document scores .7, skip the block under valid bounds.','Fast exact top-k retrieval for supported additive lexical or sparse scores.','Safe skipping needs valid bounds and scoring assumptions; not every pruning strategy is exact.',['boolean','bm25'])
method(c,'Exact vector scan & flat indexes','REFERENCE','Compute the chosen vector score for every eligible item, retaining top-k. This is the reference used to measure ANN errors.','work ≈ number_of_vectors × dimensions','With 6 vectors and k=2, score all 6 and select the two best.','Small collections, batched GPU search and correctness baselines.','Work grows with collection size; “exact” refers to vector arithmetic, not semantic truth.',['faiss'])
method(c,'HNSW & graph ANN','APPROXIMATE','Navigate a hierarchy of neighbor graphs, moving from coarse routing to a broader local candidate search.','larger search breadth → usually more work and better neighbor recall','Visit a few promising neighborhoods instead of comparing every vector. efSearch controls search breadth, not embedding quality.','Low-latency vector search with a suitable memory budget.','Memory, build cost and filter behavior matter. Higher breadth does not guarantee monotonic relevance on every query.',['hnsw'])
method(c,'IVF, product quantization & hashing','PARTITION / COMPRESS','IVF searches selected coarse clusters; PQ encodes subvectors using compact codebooks; LSH routes through probabilistic hash collisions. These can be composed with other index choices.','IVF: probe nprobe of nlist clusters','A boundary document in an unprobed cluster is missed. Probe more clusters to trade speed for neighbor coverage.','Large vector collections and memory-constrained services.','Partition misses and quantization distortion are different error sources. Faiss is a library containing many index types, not a single algorithm.',['faiss'])

c=category('ranking','Rankers & rerankers','Spend more computation on fewer items','2000s → today','Which candidates actually satisfy this query?',
 'A first-stage retriever is already a ranker. A reranker spends extra effort on its shortlist. Learning to rank can combine engineered features, cross-encoders can inspect query-document interactions, and LLMs can compare candidates as a list.',
 'A reranker can repair an order, but it cannot promote a relevant document absent from its input. Candidate depth is both a quality ceiling and a computation budget.',['ltr','bert','rankzephyr','retrievearticle'])
method(c,'Learning to rank · pointwise, pairwise, listwise','LEARNING OBJECTIVE','Pointwise learning predicts a per-item label; pairwise learning learns preferences; listwise objectives consider a ranked list or a list-dependent target.','pairwise loss = log(1 + exp(−(spositive − snegative)))','Increasing a positive-negative score margin reduces this logistic pairwise loss. It does not directly calibrate relevance probability.','Ranking with text scores, freshness, authority, metadata and interaction features.','Click labels carry position and presentation biases. Split data by query and time where appropriate.',['ltr'])
method(c,'LambdaMART & boosted tree rankers','FEATURE-BASED','Fit boosted trees using ranking gradients weighted by the metric impact of swaps. Features can include BM25, dense scores and domain signals.','swap importance ∝ |ΔNDCG|','Moving a highly relevant result from rank 20 to rank 1 may matter more than swapping two weak tail results.','Strong tabular-feature ranking and interpretable feature inspection.','Requires representative judgments and leakage control; feature importance is not a causal explanation.',['ltr','ltrstory'])
method(c,'Cross-encoder reranking','JOINT ENCODING','Pass query and candidate together through a model, allowing token interactions across both before assigning a score.','score(q,d) = model([query ; document])','For “does not need lithium”, a joint model can potentially prefer an appropriate alternative over a lithium-heavy document.','High-quality reranking of tens or hundreds of candidates.','Potentially expensive per pair; truncation can hide the answer. Models may still mishandle negation or domain terminology.',['bert','retrievearticle'])
method(c,'LLM pairwise & listwise reranking','GENERATIVE JUDGMENT','Ask a model to compare pairs or output a permutation of candidate IDs. Train or prompt it for relevance; validate that output IDs belong to the shortlist.','candidates [A,B,C] → permutation [C,A,B]','A listwise prompt can judge which passage answers the specific question rather than merely sharing a topic.','Complex relevance criteria and instruction-following ranking.','Order bias, context limits, cost and invalid permutations. Retrieved instructions should be treated as document content.',['rankzephyr'])

c=category('fusion','Hybrid, fusion & diversity','Let different evidence cooperate','1990s → today','How should several ranked lists become one?',
 'Lexical and semantic retrievers make different errors. Hybrid search combines them; fusion specifies how. Rank fusion needs only positions, whereas score fusion needs meaningful scales. Diversification then changes the set to avoid repeating the same evidence.',
 '“Hybrid” is an architecture choice, not a guarantee of better results. Complementary candidates and a validated combination rule matter more than the number of engines.',['rrf','mmr','beir'])
method(c,'Candidate union, intersection & cascades','COMPOSITION','Union broadens candidate coverage; intersection favors agreement; a cascade applies stages in sequence. Preserve provenance and deduplicate identities.','Cunion = Clexical ∪ Cdense','If A retrieves [1,2] and B retrieves [2,3], the union has 3 items and the intersection has only item 2.','Combining specialists or applying a costly scorer after cheap retrieval.','Union increases downstream work; intersection can discard unique useful evidence; a cascade inherits earlier omissions.',['rrf','retrievearticle'])
method(c,'Reciprocal rank fusion · RRF','RANK-BASED','Add reciprocal contributions from each list. Missing documents contribute zero; ranks begin at 1. Weighted RRF changes each list’s contribution.','RRF(d) = Σlists weight(list) / (k + ranklist(d))','With k=60, ranks 1 and 3 contribute 1/61 + 1/63 = .03227. An item only at rank 1 contributes .01639.','Combining incomparable score scales without fitting a score calibration.','Truncation and correlated lists matter. k is a smoothing constant, not the number of returned results. Duplicating a list doubles its vote.',['rrf'])
method(c,'Score fusion · weighted sum, CombSUM, CombMNZ','SCORE-BASED','Normalize or calibrate compatible scores, then combine them. CombMNZ multiplies a score sum by the number of nonzero contributing systems.','hybrid = α × normalized_lexical + (1−α) × normalized_dense','Raw BM25=12 and cosine=.8 cannot be compared by scale alone. Per-query min–max normalization is one illustrative option.','A tunable blend when judgments support choosing weights and normalization.','Min–max is sensitive to outliers and candidate depth; normalized scores are not automatically calibrated probabilities.',['rrf','bm25'])
method(c,'Borda-style voting & learned fusion','VOTING / LEARNING','Convert positions into votes or learn a combination from labeled queries. Include missingness explicitly when sources have different candidate sets.','Borda points = list_length − rank + 1','An item ranked second by two length-3 lists receives 2+2 points under this stated convention.','Rank aggregation and domain-specific fusion with sufficient validation data.','Borda depends on list length; supervised fusion can overfit the benchmark or leak query labels.',['rrf','ltr'])
method(c,'MMR & diversity-aware selection','SET UTILITY','Select items greedily by balancing query relevance against similarity to already selected items.','MMR(d) = λ relevance(d) − (1−λ) maxselected similarity(d,selected)','Two near-duplicate battery articles may be less useful than one battery article and a complementary grid report.','RAG context selection, varied recommendations and multi-aspect search.','Diversity can displace the most relevant item. Similarity and relevance scales must be compatible; the first selection needs a defined convention.',['mmr'])

c=category('structured','Graphs, hierarchy & structured search','Retrieve relationships and context','1990s → today','Does the answer live between documents?',
 'Some questions require links between entities, exact field constraints, several evidence hops, or summaries spanning many sections. Graphs, trees and relational filters make these structures explicit rather than treating every item as an isolated chunk.',
 'PageRank, a two-hop knowledge-graph lookup, RAPTOR and Microsoft GraphRAG solve different problems. Sharing a graph or hierarchy does not make them the same retrieval model.',['pagerank','raptor','graphrag'])
method(c,'Link analysis · PageRank & authority','GLOBAL SIGNAL','Propagate importance over a link graph, often combining the resulting query-independent authority with query-dependent text relevance.','PR(v) = (1−d)/N + d Σu→v PR(u)/outdegree(u)','A frequently cited page may receive authority, while a query-specific term score decides whether it discusses the requested subject.','Web search, citations and graph-based importance features.','Authority does not imply relevance or correctness; link spam and graph design affect scores.',['pagerank'])
method(c,'Entity, relational & multi-hop retrieval','EXPLICIT RELATIONSHIPS','Resolve entities and follow constrained relationships, sometimes using intermediate results to issue another search.','company → makes → product → uses → material','“Which material is used by a product made by Aurora?” needs the product link and the material link if neither passage states both.','Knowledge graphs, catalogs and questions needing join-like evidence.','Entity resolution and missing edges limit coverage. A retrieved path is only as reliable as its supporting records.',['graphrag','brightpro'])
method(c,'Hierarchical retrieval & RAPTOR','ABSTRACTION','Index leaves alongside higher-level summaries. Retrieve detail, overview or both; expand a matched summary back to original evidence.','chunks → clusters → summaries → recursive tree','“What changed across the full report?” may be better served by section summaries before drilling into passages.','Long documents, corpus navigation and questions spanning multiple sections.','Summary generation costs time and can omit or distort details. Keep pointers to original passages.',['raptor'])
method(c,'GraphRAG community retrieval','CORPUS-LEVEL SYNTHESIS','Extract an entity graph, detect communities and summarize them. Use relevant community reports to support broader query-focused synthesis.','documents → entity graph → community reports → synthesis','“What themes connect this organization’s projects?” needs broader coverage than one nearest paragraph.','Global questions about relationships and themes across a corpus.','Indexing expense, extraction errors and summary freshness. A graph does not automatically improve simple factual lookups.',['graphrag'])

c=category('multimodal','Multimodal & domain similarity','Beyond plain text','2021 → today','What if the useful signal is visual or scientific?',
 'Retrieve images, rendered pages, audio or domain objects through a representation and distance suited to the signal. Text and visual encoders can share a space; page-level multi-vector models can preserve tables and layout that text extraction loses.',
 'A scientific similarity score and a text relevance score answer different questions. The shared pipeline pattern is useful, but each domain needs its own ground truth and metric.',['clip','colpali'])
method(c,'Cross-modal contrastive retrieval · CLIP','SHARED SPACE','Train image and text encoders so paired examples align. At search time, compare a text vector against image vectors or vice versa.','score(text,image) = normalized_text · normalized_image','“a chart of energy storage capacity” can retrieve a visual object without requiring identical text in its filename.','Image search and mixed visual/text collections.','Visual similarity need not satisfy an analytical question; OCR details, counts and spatial relations may be missed.',['clip'])
method(c,'Visual document retrieval · ColPali','PAGE REPRESENTATION','Encode document-page images as multiple vectors; match a query to page patches through late interaction.','query tokens ↔ rendered-page patch vectors','A query about a row in a table can use the page’s visual structure instead of relying only on extracted reading order.','PDFs with figures, tables, charts and complex layouts.','Resolution, page rendering, patch storage and benchmark coverage matter. The lab is a schematic, not a running vision model.',['colpali'])
method(c,'Domain-specific nearest-neighbor retrieval','DOMAIN REPRESENTATIONS','Use an appropriate feature space and similarity for the object: spectra, molecular fingerprints, audio features or other measured signals.','binary fingerprint Tanimoto(A,B) = |A∩B| / |A∪B|','Fingerprints {a,b,c} and {b,c,d} have Tanimoto 2/4 = .5. This is not a text embedding cosine.','Scientific libraries and domains where precise measurement or structural matching defines similarity.','A similar spectrum or fingerprint is not proof of identity. This is an analogy to the companion CASMI atlas, not a claim that CLIP retrieves molecules.',['clip','colpali'])

c=category('frontier','Generative & agentic retrieval','Retrieve, reason, check, repeat','2020 → 2026','Can search adapt as evidence arrives?',
 'Modern research combines stronger encoders with query reasoning, generated identifiers, adaptive retrieval and multi-stage evidence selection. These are branches of research rather than one universal replacement for lexical search.',
 'Research snapshot: 20 October 2026. “State of the art” is benchmark-, budget-, language- and protocol-specific. The papers below are representative advances; no permanent leaderboard winner is claimed.',['rag','dsi','selfrag','qwen','diver','brightpro'])
method(c,'Generative retrieval · DSI','GENERATE IDENTIFIERS','Train a sequence model to map queries to valid document IDs. The model acts as a learned index rather than simply generating answer prose.','query → sequence model → docID → stored document','A constrained decoder emits “doc-42”, then the system loads document 42 and checks its eligibility.','Research on model-based indexing and learned semantic identifiers.','Adding or deleting corpus items and constraining valid IDs are core challenges. Generated IDs still need resolution and access checks.',['dsi'])
method(c,'Retrieval-augmented generation · RAG','ARCHITECTURE','Retrieve evidence and condition a generator on it. A RAG pipeline can use Boolean, BM25, dense, sparse or hybrid retrieval.','retrieve(q) → context → generate(q,context)','Find real passages about storage before generating an explanation with references to those passages.','Grounding answers in external or updated information.','A correct retrieval set does not guarantee a faithful answer. Evaluate retrieval and generation separately.',['rag'])
method(c,'Adaptive retrieval & Self-RAG','CONTROL POLICY','Decide whether more retrieval is needed and assess evidence or generation during the process. Self-RAG learns special reflection tokens for these choices.','retrieve? → evidence → critique → continue or answer','A simple known question may need no new search; an unresolved factual dependency may trigger retrieval.','Reducing unnecessary retrieval and improving evidence use in trained systems.','A generic retry loop is not an implementation of Self-RAG. Critiques can be mistaken and need external validation.',['selfrag'])
method(c,'Reasoning-aware multi-stage retrieval','QUERY REASONING','Explain the hidden information need, expand queries iteratively and combine specialized retrieval with reranking. DIVER is one recent concrete pipeline.','reason → expand → retrieve → rerank → revise','A software error may require recognizing the underlying algorithmic condition before the right documentation becomes retrievable.','Queries whose relevant evidence shares little surface wording with the original question.','Reasoning text can drift or invent constraints; compare against simpler methods at matched cost and candidate budgets.',['diver','bright'])
method(c,'Agentic & complementary-evidence search','ITERATIVE SEARCH','Track missing evidence aspects, issue targeted searches, verify progress and stop under a budget. Recent evaluation examines evidence portfolios rather than one good hit.','missing_aspects = required_aspects − supported_aspects','A comparison needs cost and durability evidence. After finding cost, search specifically for durability rather than retrieving another cost article.','Multi-step research, multi-aspect questions and tool-using systems.','Repeated search can reinforce an early error. Track provenance, redundant evidence, latency and a clear stop rule.',['brightpro'])

TIMELINE = [
('1957','Statistical indexing','From catalog labels to word patterns. Luhn explores how machines can encode and search literature.','lexical','luhn'),
('1950s–60s','Boolean document search','Term sets and logical operators turn an information request into an exact selection rule. This era is an approximate development period, not a single invention date.','boolean','boolean'),
('1960s','SMART and ranked retrieval','Experimental automatic retrieval systems develop weighting and feedback ideas. The 1975 vector-space paper is a later landmark in this line.','lexical','vsm'),
('1971','Relevance feedback','Rocchio formalizes moving a query toward relevant examples and away from irrelevant ones.','expansion','rocchio'),
('1975','The vector-space landmark','Salton, Wong and Yang formulate documents and requests in a weighted geometric space.','lexical','vsm'),
('1977','Probability Ranking Principle','Relevance uncertainty becomes an explicit ranking perspective; later probabilistic models build practical estimators.','probabilistic','prob'),
('1990','Latent semantic indexing','Low-rank factorization offers an early bridge across vocabulary differences, well before transformer embeddings.','dense','lsi'),
('1992','TREC begins','Shared test collections and judgments make retrieval experiments easier to compare and reproduce.','evaluation','trec'),
('1990s','Okapi BM25 matures','Term-frequency saturation and length normalization become a durable lexical baseline. The linked 2009 review explains the lineage.','probabilistic','bm25'),
('1998','Language models for retrieval','Ponte and Croft ask how likely a document model would be to generate a query.','probabilistic','lm'),
('1998','Links and diversified results','Web link analysis supplies authority signals; MMR separately addresses redundant result sets.','structured','pagerank'),
('2005 → 2010','Learning to rank','RankNet, LambdaRank and LambdaMART learn relevance order from data. The linked overview was published in 2010.','ranking','ltr'),
('2009','Reciprocal rank fusion','Combine result positions without forcing different engines onto one raw-score scale.','fusion','rrf'),
('2016–17','Scalable vector lookup','HNSW and GPU similarity-search research make larger vector collections practical. Dates refer to initial preprints.','indexes','hnsw'),
('2019','BERT reranking and reusable embeddings','Cross-encoders strengthen pair scoring; SBERT makes independent sentence embeddings practical; doc2query expands documents.','ranking','bert'),
('2020','Dense passages, token vectors and RAG','DPR, ColBERT and retrieval-augmented generation develop three distinct but composable ideas.','dense','dpr'),
('2021','Learned sparse and broader evaluation','SPLADE learns sparse expansion; BEIR tests cross-domain transfer; CLIP connects image and text representations.','sparse','splade'),
('2021–22','Compact late interaction','ColBERTv2 reduces multi-vector storage and improves supervision. Preprint 2021; NAACL publication 2022.','late','colbert2'),
('2022','Model-generated IDs and hypotheses','DSI generates document IDs; HyDE generates a hypothetical document to steer actual dense retrieval.','frontier','dsi'),
('2023','LLM ranking and adaptive retrieval','RankZephyr explores listwise ranking; Self-RAG learns when to retrieve and how to critique. These are different system components.','ranking','rankzephyr'),
('2024','Graphs, hierarchies and visual pages','GraphRAG, RAPTOR and ColPali use richer corpus structures. BRIGHT stresses relevance requiring reasoning.','structured','graphrag'),
('2025','Task-aware and reasoning pipelines','Qwen3 Embedding and DIVER illustrate stronger task conditioning, training and multi-stage query reasoning.','frontier','qwen'),
('2026','Complementary evidence and agentic evaluation','BRIGHT-Pro studies search as iterative evidence collection; DIVER’s April revision also develops reasoning-intensive retrieval.','frontier','brightpro'),
]

